iterate.script:
try {
    lib.probe("create#mantle.account.method.PaymentMethodTrans", newLine)
    row.status = "imported"
} catch (error) {
    const known = lib.one("mantle.account.method.PaymentMethodTrans",
        {paymentMethodId: found.paymentMethodId, fitId: row.fitId})
    row.status = known ? "duplicate" : "failed"
    row.error = known ? null : error.message
    if (!known) ec.logger.error("Statement import " + statementImportId + " row " + row.sourceRow + ": " +
        error.message)
}

service-call.in-map:
{statementImportId:statementImportId, statusId:'SimCommitted', committedCount:committedCount,
                        duplicateCount:duplicateCount, rowsJson:JSON.stringify(rows), committedByUserId:ec.user.userId,
                        committedDate:ec.user.nowTimestamp}

{bankReconciliationId:bankReconciliationId,
                            statementReference:statementReference != null ? statementReference : found.statementReference,
                            closingBalance:closingBalance != null ? closingBalance : found.closingBalance}
